#pragma once
// ============================================================================
// Ace Combat Zero: The Belkan War (PC Port) — Extended Draw Distance Engine
// File: acz_draw_distance.h (v0.25)
//
// Unified maximum-realism DrawDistance engine (disabled by default via
// DrawDistance=0 in mods\enhancer\enhancer.ini):
//   - 4x realistic horizon (~25-30 km, 33x33 coarse tile grid with circular
//     closest-corner culling behind the fog wall)
//   - Automatic O(1) precomputed 2D-mirrored fractal OOB terrain extension
//     with CPU-cached staging (Hook_DrawMeshTemp) & GPU UV-mirroring
//     (Hook_FlushMeshTemp)
//   - Universal stage environment handler: applies curated atmosphere-aware
//     presets for all 64 known Campaign/Free/Gauntlet/Valais stage IDs AND
//     dynamically extends native 864-byte env blocks for all remaining stages
//     and modes (VS Mode v01a-v08a, fr1a, 2P Co-Op, takeoff/landing/refuel,
//     cutscenes, Scene Viewer)
//   - Skybox polygon & Z-precision fix on 4x: caps Camera FarZ to 524,288.0f
//     (2x terrain cull radius, preserving 2x better 24-bit Z precision vs
//     1,048,576.0f) and avoids scaling skybox dome parameter idx 2 when <=16384
//   - Full 524,288 x 524,288 world-origin WRAP cloud shadow map & max terrain
//     self-shadow/detail LOD (Path A & Path B)
//   - Dual-version compatible (acz.exe v1.0.2.1 & Steam v2.0.0.1)
// ============================================================================

#include <windows.h>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <atomic>

// Cross-plugin queryable state structure (exported via AczEnhancer_GetDrawDistanceState)
struct AczDrawDistanceState {
    uint32_t struct_size;           // sizeof(AczDrawDistanceState)
    uint32_t enabled;               // 1 if DrawDistance=1 is active
    uint32_t radial_fog_enabled;    // 1 if RadialFog=1 is active
    uint32_t radial_fog_pso_count;  // Number of patched D3D12 PSOs
    int32_t  last_stage_id;         // Last processed stage_id (-1 if none yet)
    uint32_t last_stage_mode;       // 0 = none, 1 = preset, 2 = universal_dynamic
    float    effective_far_z;       // Active camera FarZ (65535.0f vanilla, 524288.0f extended)
    int32_t  coarse_grid_radius;    // 6 (13x13 vanilla) or 16 (33x33 extended)
};

