using FnInstallHook  = bool (*)(const char* name, uintptr_t target_addr, const uint8_t* expected_prologue, size_t prologue_len, const void* hook_fn, void** out_trampoline);
using FnLogMsg       = void (*)(const char* fmt, ...);

