static std::atomic<uint32_t> g_PerfGridCpuUs{0};
static std::atomic<uint32_t> g_PerfFlushInstTotal{0};
static std::atomic<uint32_t> g_PerfFlushInstOob{0};
static std::atomic<uint32_t> g_PerfFlushCpuUs{0};
static double                g_PerfQpcToUs = 0.0;

static inline uint32_t QpcDeltaToUs(int64_t t0, int64_t t1) {
    if (g_PerfQpcToUs <= 0.0) {
        LARGE_INTEGER freq{};
        QueryPerformanceFrequency(&freq);
        if (freq.QuadPart > 0) g_PerfQpcToUs = 1000000.0 / static_cast<double>(freq.QuadPart);
    }
    return (t1 > t0 && g_PerfQpcToUs > 0.0) ? static_cast<uint32_t>(static_cast<double>(t1 - t0) * g_PerfQpcToUs) : 0u;
}

