// Unified maximum-realism extended draw distance constants (artifact-free 2x skybox/engine limit + 60 FPS):
//   - 19x19 coarse tile grid with circular culling behind 122,880 spherical fog wall (zero pop-in)
//   - High->Low terrain LOD transition at 65,536 for locked 60 FPS at high altitude
//   - Cloud/sky dome bounds (idx 5/9) within safe 65,535 ceiling and FarZ = 262,144 (zero skybox polygon breakup)
static constexpr float kDrawScaleF           = 2.0f;
static constexpr int   kExpandedGridRadius   = 9;          // 19x19 coarse tiles
static constexpr float kMaxClosestCornerDist = 139264.0f;  // Loads coarse tiles behind 122.8k spherical fog wall
static constexpr float kMaxFogFarCap         = 122880.0f;  // Highest artifact-free FogFar before skybox breakup (>131072)
static constexpr float kMaxFogNearCap        = 24560.0f;   // Preserves natural atmospheric haze & soft cloud rim
static constexpr float kSafeCloudBoundCap    = 65535.0f;   // Safe 2x cloud/sky bound ceiling (zero PS2 GS guard-band drops)
static constexpr float kSafeCameraFarZ       = 262144.0f;  // Preserves 24-bit Z precision & skybox integrity

